import sqlite3

def kullanici_bul(kullanicilar, eposta):
    connection = sqlite3.connect(":memory:")
    connection.execute("CREATE TABLE kullanicilar (id INTEGER PRIMARY KEY, eposta TEXT UNIQUE)")
    connection.executemany(
        "INSERT INTO kullanicilar (id, eposta) VALUES (?, ?)",
        [(item["id"], item["eposta"]) for item in kullanicilar],
    )
    # HATALI: kullanıcı girdisi doğrudan SQL metnine ekleniyor.
    row = connection.execute(
        f"SELECT id, eposta FROM kullanicilar WHERE eposta = '{eposta}'"
    ).fetchone()
    connection.close()
    if row is None:
        return None
    return {"id": row[0], "eposta": row[1]}

if __name__ == "__main__":
    print(kullanici_bul(
        [{"id": 1, "eposta": "ali@example.com"},
         {"id": 2, "eposta": "ada@example.com"}],
        "ada@example.com",
    ))

